syntax:
std::unique_ptr<T> for exclusive ownership;
std::shared_ptr<T> for shared ownership;
std::weak_ptr<T> for non-owning references to shared objects.

code_example:
#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget constructed" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void do_something() { std::cout << "Doing something" << std::endl; }
};

int main() {
    // Using std::unique_ptr for exclusive ownership
    std::unique_ptr<Widget> ptr1 = std::make_unique<Widget>();
    ptr1->do_something();
    // Ownership transfers to ptr2
    std::unique_ptr<Widget> ptr2 = std::move(ptr1);
    if (!ptr1) {
        std::cout << "ptr1 is now null after move" << std::endl; }
    ptr2->do_something();
    // No need to delete; Widget is destroyed automatically when ptr2 goes out of scope
    return 0;
}
